{"explanation":"With 100% annual interest compounded n times a year, each period earns 1/n interest, so your $1 becomes (1 + 1/n)ⁿ after one year. Annual compounding gives $2, twice-yearly gives $2.25, and monthly gives about $2.61. As compounding becomes more frequent, the balance approaches e ≈ $2.71828—not infinity. Drag the yellow point to explore how the balance approaches this limit.","manimCode":"let n = 4;
const balance = k => Math.pow(1 + 1 / k, k);

const title = new Text({ text: '$1 at 100% annual interest', fontSize: 32, color: WHITE });
title.moveTo([0, 3.25, 0]);
const formula = new MathTex({ latex: 'A_n=\\left(1+\\frac{1}{n}\\right)^n\\;\\longrightarrow\\;e\\approx2.71828', color: WHITE });
await formula.waitForRender();
formula.scale(0.75);
formula.moveTo([0, 2.7, 0]);

const ax = new Axes({ xRange: [0, 32, 8], yRange: [0, 3, 1], xLength: 9.5, yLength: 4.4, tips: false });
const curve = ax.plot(x => x > 0 ? Math.exp(x * Math.log1p(1 / x)) : 1, { color: BLUE, xRange: [1, 32] });
const limitLine = new DashedLine({ start: ax.c2p(0, Math.E), end: ax.c2p(32, Math.E), color: GREEN });
const limitLabel = new Text({ text: 'Limit: $2.71828...', fontSize: 21, color: GREEN });
limitLabel.moveTo([2.8, 2.08, 0]);
const guide = new DashedLine({ start: ax.c2p(n, 0), end: ax.c2p(n, balance(n)), color: YELLOW });
const handle = new Dot({ point: ax.c2p(n, balance(n)), radius: 0.13, color: YELLOW });
const readout = new Text({ text: '', fontSize: 26, color: YELLOW });
readout.moveTo([0, -2.94, 0]);
const hint = new Text({ text: 'Drag the yellow point left or right: more compounding periods per year', fontSize: 19, color: GRAY });
hint.moveTo([0, -3.4, 0]);
const verticalLabel = new Text({ text: 'Balance\nafter\none year', fontSize: 20, color: WHITE });
verticalLabel.moveTo([-5.55, 0.35, 0]);
const axisLabel = new Text({ text: 'Compounding periods per year (n)', fontSize: 19, color: WHITE });
axisLabel.moveTo([0, -2.58, 0]);

scene.add(ax, limitLine, curve, guide, handle, limitLabel, readout, hint, verticalLabel, axisLabel);
for (const k of [0, 8, 16, 24, 32]) {
  const tickLabel = new Text({ text: String(k), fontSize: 16, color: GRAY });
  const p = ax.c2p(k, 0);
  tickLabel.moveTo([p[0], p[1] - 0.17, 0]);
  scene.add(tickLabel);
}
for (const k of [1, 2, 3]) {
  const dollarLabel = new Text({ text: '$' + k, fontSize: 17, color: GRAY });
  const p = ax.c2p(0, k);
  dollarLabel.moveTo([p[0] - 0.28, p[1], 0]);
  scene.add(dollarLabel);
}

function update() {
  const amount = balance(n);
  handle.moveTo(ax.c2p(n, amount));
  guide.setStart(ax.c2p(n, 0));
  guide.setEnd(ax.c2p(n, amount));
  readout.setText('n = ' + n + '    |    Balance = $' + amount.toFixed(6) + '    |    Below limit by $' + (Math.E - amount).toFixed(6));
}
update();
await scene.play(new AnimationGroup([new Write(title), new FadeIn(formula)]));

makeDraggable(handle, scene, {
  onDrag: (mob, pos) => {
    const coords = ax.pointToCoords(pos);
    n = Math.max(1, Math.min(32, Math.round(coords[0])));
    update();
  }
});
const details = new Text({ text: '', fontSize: 20, color: WHITE });
details.moveTo([0, -0.8, 0]);
makeHoverable(handle, scene, {
  onHoverStart: () => {
    details.setText('Each period earns 100% / ' + n + ' = ' + (100 / n).toFixed(2) + '%');
    scene.add(details);
  },
  onHoverEnd: () => scene.remove(details)
});
await scene.wait(999999);"}

